function CustomInput(props) {
  return <input {...props} />;
}

// This won't work - ref isn't passed through
function Form() {
  const ref = useRef();
  return <CustomInput ref={ref} />; // Error or undefined
}

import { forwardRef } from 'react';

const CustomInput = forwardRef((props, ref) => {
  return <input {...props} ref={ref} />;
});

// Now this works
function Form() {
  const ref = useRef();

  const focusInput = () => {
    ref.current.focus();
  };

  return (
    <>
      <CustomInput ref={ref} />
      <button onClick={focusInput}>Focus</button>
    </>
  );
}
